pub fn testYymmdd() {
    let mut exchange = crate::tests_support::make_exchange(Value::Map({
        let mut m = indexmap::IndexMap::new();
            m.insert("id".to_string(), Value::Str("sampleexchange".to_string()));
        m
    }));
    let mut testMs: Value = Value::Int(1750123456789); // 17 June 2025
    let mut value: Value = exchange.yymmdd(testMs.clone(), &[Value::Str("_".to_string())]);
    assert!(ccxt::runtime::is_true(&(Value::Bool(is_equal(&value, &Value::Str("25_06_17".to_string()))))));
    let mut value2: Value = exchange.yymmdd(exchange.milliseconds(), &[]);
    assert!(ccxt::runtime::is_true(&(Value::Bool(is_equal(&get_array_length(&value2), &Value::Int(6))))));
    let mut intNum: Value = exchange.parse_to_int(value2.clone());
    assert!(ccxt::runtime::is_true(&(Value::Bool(is_greater_than(&intNum, &Value::Int(260000)) && is_less_than(&intNum, &Value::Int(360000)))))); // date between 2026 and 2036
}
pub fn testYyyymmdd() {
    let mut exchange = crate::tests_support::make_exchange(Value::Map({
        let mut m = indexmap::IndexMap::new();
            m.insert("id".to_string(), Value::Str("sampleexchange".to_string()));
        m
    }));
    let mut testMs: Value = Value::Int(1750123456789); // 17 June 2025
    let mut value: Value = exchange.yyyymmdd(testMs.clone(), &[Value::Str("_".to_string())]);
    assert!(ccxt::runtime::is_true(&(Value::Bool(is_equal(&value, &Value::Str("2025_06_17".to_string()))))));
    let mut value2: Value = exchange.yyyymmdd(exchange.milliseconds(), &[]);
    assert!(ccxt::runtime::is_true(&(Value::Bool(is_equal(&get_array_length(&value2), &Value::Int(10))))));
    let mut intNum: Value = exchange.parse_to_int(replace_str(&(replace_str(&value2, &Value::Str("-".to_string()), &Value::Str("".to_string()))), &Value::Str("-".to_string()), &Value::Str("".to_string())));
    assert!(ccxt::runtime::is_true(&(Value::Bool(is_greater_than(&intNum, &Value::Int(20260000)) && is_less_than(&intNum, &Value::Int(20360000)))))); // date between 2026 and 2036
}
